/**
 * Generate the desktop app-icon React components from the delivered
 * Bucket F v2 SVG set (assets/v2/app-icons/svg, 104 icons, hand-drawn
 * 24×24 currentColor strokes). Zero new dependencies — the SVGs are
 * simple path/circle/rect/ellipse markup, converted mechanically:
 *
 *   bun run scripts/generate-app-icons.ts
 *
 * Emits one .tsx per icon into desktop/src/components/icons/ plus an
 * index.tsx barrel (components, ICONS map, IconName, <AppIcon/>).
 * Re-run after refreshing assets/v2/ (scripts/fetch-v2-assets.sh).
 * Never hand-edit the generated files.
 */
import { mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const SRC = join(import.meta.dir, '..', 'assets', 'v2', 'app-icons', 'svg');
const OUT = join(import.meta.dir, '..', 'desktop', 'src', 'components', 'icons');

const ATTR_MAP: Record<string, string> = {
  'stroke-width': 'strokeWidth',
  'stroke-linecap': 'strokeLinecap',
  'stroke-linejoin': 'strokeLinejoin',
  'stroke-dasharray': 'strokeDasharray',
  'fill-rule': 'fillRule',
  'clip-rule': 'clipRule',
  'stroke-miterlimit': 'strokeMiterlimit',
};

function toJsxAttrs(attrs: string): string {
  return attrs.replace(/([a-zA-Z-]+)="([^"]*)"/g, (_m, name: string, value: string) => {
    const jsx = ATTR_MAP[name] ?? name;
    return `${jsx}="${value}"`;
  });
}

function pascal(name: string): string {
  return name
    .split('-')
    .map((p) => p.charAt(0).toUpperCase() + p.slice(1))
    .join('');
}

mkdirSync(OUT, { recursive: true });

const files = readdirSync(SRC).filter((f) => f.endsWith('.svg')).sort();
const names: string[] = [];

for (const file of files) {
  const base = file.replace(/\.svg$/, '');
  const component = pascal(base);
  names.push(base);
  const svg = readFileSync(join(SRC, file), 'utf8').trim();
  const root = svg.match(/<svg([^>]*)>/);
  const inner = svg.replace(/<svg[^>]*>/, '').replace(/<\/svg>\s*$/, '').trim();
  if (!root) throw new Error(`${file}: no <svg> root`);

  let rootAttrs = toJsxAttrs(root[1])
    .replace(/\s*xmlns="[^"]*"/, '')
    .replace(/\s*width="[^"]*"/, '')
    .replace(/\s*height="[^"]*"/, '')
    .trim();

  const body = `/**
 * ${component} — delivered Bucket F v2 app icon (${base}).
 * GENERATED by scripts/generate-app-icons.ts from assets/v2/app-icons/svg/${file}.
 * Do not hand-edit; re-run the generator after a pack refresh.
 */
import type { SVGProps } from 'react';

export interface AppIconProps extends SVGProps<SVGSVGElement> {
  size?: number;
}

export function ${component}({ size = 24, ...props }: AppIconProps) {
  return (
    <svg
      width={size}
      height={size}
      ${rootAttrs}
      aria-hidden={props['aria-label'] ? undefined : true}
      focusable="false"
      {...props}
    >
${inner.split('\n').map((l) => `      ${toJsxAttrs(l.trim())}`).join('\n')}
    </svg>
  );
}
`;
  writeFileSync(join(OUT, `${base}.tsx`), body);
}

const barrel = `/**
 * XR app-icon library (Phase 31 · Bucket F v2) — 104 delivered icons,
 * generated by scripts/generate-app-icons.ts. Stroke icons inherit
 * currentColor: set color via CSS (accent when active, text-dim when not).
 */
import type { ComponentType } from 'react';

${names.map((n) => `import { ${pascal(n)} } from './${n}';`).join('\n')}

${names.map((n) => `export { ${pascal(n)} } from './${n}';`).join('\n')}
export type { AppIconProps } from './${names[0]}';

export const ICONS = {
${names.map((n) => `  '${n}': ${pascal(n)},`).join('\n')}
} as const;

export type IconName = keyof typeof ICONS;

export interface AppIconComponentProps {
  size?: number;
  className?: string;
  'aria-label'?: string;
}

/** Render any delivered icon by name: <AppIcon name="nav-chat" size={20} /> */
export function AppIcon({
  name,
  size = 24,
  className,
  'aria-label': ariaLabel,
}: { name: IconName } & AppIconComponentProps) {
  const Cmp = ICONS[name] as ComponentType<AppIconComponentProps & { size?: number }>;
  return <Cmp size={size} className={className} aria-label={ariaLabel} />;
}
`;
writeFileSync(join(OUT, 'index.tsx'), barrel);
console.log(`generated ${names.length} icons -> ${OUT}`);
